// Generated from src/registry/sources/control-ui/recipes/markdown.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const markdownKnobs = [
  "--cui-markdown-foreground",
  "--cui-markdown-blockquote-border-color",
  "--cui-markdown-blockquote-foreground",
  "--cui-markdown-inline-code-background",
  "--cui-markdown-inline-code-foreground",
  "--cui-markdown-inline-code-radius",
  "--cui-markdown-link-foreground",
  "--cui-markdown-table-cell-border-color",
  "--cui-markdown-table-header-background",
] as const;
export type MarkdownKnobStyle = Partial<Record<(typeof markdownKnobs)[number], string>>;

@layer components {
  :where([data-control-family="markdown"][data-slot="root"]) {
    --cui-markdown-foreground: oklch(from var(--foreground) l c h / 0.9);
    --cui-markdown-blockquote-border-color: var(--border);
    --cui-markdown-blockquote-foreground: var(--muted-foreground);
    --cui-markdown-inline-code-background: color-mix(in oklab, var(--foreground) 8%, transparent);
    --cui-markdown-inline-code-foreground: var(--foreground);
    --cui-markdown-inline-code-radius: 0.25rem;
    --cui-markdown-link-foreground: var(--primary-text);
    --cui-markdown-table-cell-border-color: var(--border);
    --cui-markdown-table-header-background: var(--muted);
    color: var(--cui-markdown-foreground);
    font-size: var(--text-label);
  }

  :where([data-control-family="markdown"][data-slot="table-cell"]) {
    border-style: solid;
    border-width: 1px;
    border-color: var(--cui-markdown-table-cell-border-color);
  }

  :where([data-control-family="markdown"][data-slot="table-header"]) {
    border-style: solid;
    border-width: 1px;
    border-color: var(--border);
    background-color: var(--cui-markdown-table-header-background);
    text-align: left;
    font-weight: var(--font-weight-semibold);
  }

  :where([data-control-family="markdown"][data-slot="table"]) {
    border-collapse: collapse;
    font-size: var(--text-label);
  }

  :where([data-control-family="markdown"][data-slot="emphasis"]) {
    font-style: italic;
  }

  :where([data-control-family="markdown"][data-slot="strong"]) {
    font-weight: var(--font-weight-semibold);
    color: var(--foreground);
  }

  :where([data-control-family="markdown"][data-slot="separator"]) {
    border-color: var(--border);
  }

  :where([data-control-family="markdown"][data-slot="blockquote"]) {
    border-color: var(--cui-markdown-blockquote-border-color);
    border-left-style: solid;
    border-left-width: 2px;
    color: var(--cui-markdown-blockquote-foreground);
    font-style: italic;
  }

  :where([data-control-family="markdown"][data-slot="link"]) {
    font-weight: var(--font-weight-medium);
    color: var(--cui-markdown-link-foreground);
    --_markdown-link-decoration: underline;
    text-decoration-line: var(--_markdown-link-decoration);
    text-underline-offset: 2px;
  }

  @media (hover: hover) {
    :where([data-control-family="markdown"][data-slot="link"]:hover) {
      --_markdown-link-decoration: none;
      text-decoration-line: var(--_markdown-link-decoration);
    }
  }

  :where([data-control-family="markdown"][data-slot="list-item"]) {
    line-height: calc(var(--spacing) * 7);
  }

  :where([data-control-family="markdown"][data-slot="paragraph"]) {
    line-height: calc(var(--spacing) * 7);
  }

  :where([data-control-family="markdown"][data-slot="h3"]) {
    font-weight: var(--font-weight-semibold);
    font-size: var(--text-base);
    line-height: var(--text-base--line-height);
    color: var(--foreground);
  }

  :where([data-control-family="markdown"][data-slot="h2"]) {
    font-weight: var(--font-weight-semibold);
    font-size: var(--text-lg);
    line-height: var(--text-lg--line-height);
    color: var(--foreground);
  }

  :where([data-control-family="markdown"][data-slot="h1"]) {
    font-weight: var(--font-weight-semibold);
    font-size: var(--text-xl);
    line-height: var(--text-xl--line-height);
    color: var(--foreground);
  }

  :where([data-control-family="markdown"][data-slot="inline-code"]) {
    border-radius: var(--cui-markdown-inline-code-radius);
    background-color: var(--cui-markdown-inline-code-background);
    font-family: var(--font-mono);
    font-size: 0.9em;
    color: var(--cui-markdown-inline-code-foreground);
  }
}

@property --cui-markdown-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

